import java.io.*; import java.util.*; import java.util.stream.*; class Result { public static long journeyToMoon(int n, List<List<Integer>> astronaut) { int[] parent = new int[n]; for (int i = 0; i < n; i++) parent[i] = i; for (List<Integer> pair : astronaut) { int root1 = find(parent, pair.get(0)); int root2 = find(parent, pair.get(1)); if (root1 != root2) parent[root1] = root2; } Map<Integer, Long> counts = new HashMap<>(); for (int i = 0; i < n; i++) { int root = find(parent, i); counts.put(root, counts.getOrDefault(root, 0L) + 1); } long totalPairs = (long) n * (n - 1) / 2; for (long size : counts.values()) { totalPairs -= (size * (size - 1) / 2); } return totalPairs; } private static int find(int[] parent, int i) { if (parent[i] == i) return i; return parent[i] = find(parent, parent[i]); } } public class Solution { public static void main(String[] args) throws IOException { BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in)); BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH"))); String[] firstMultipleInput = bufferedReader.readLine().replaceAll("\\s+$", "").split(" "); int n = Integer.parseInt(firstMultipleInput[0]); int p = Integer.parseInt(firstMultipleInput[1]); List<List<Integer>> astronaut = new ArrayList<>(); for (int i = 0; i < p; i++) { String[] line = bufferedReader.readLine().replaceAll("\\s+$", "").split(" "); List<Integer> pair = new ArrayList<>(); pair.add(Integer.parseInt(line[0])); pair.add(Integer.parseInt(line[1])); astronaut.add(pair); } long result = Result.journeyToMoon(n, astronaut); bufferedWriter.write(String.valueOf(result)); bufferedWriter.newLine(); bufferedReader.close(); bufferedWriter.close(); } }